{
  "probability": 0.96,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Late-Feb polls show CDU ahead by a narrow margin (~2–6 points).",
    "Greens closing the gap in some surveys increases risk for CDU securing the most seats.",
    "Prediction markets and expert polls largely align with CDU-first, though outcomes remain probabilistic under BW's MMP system.",
    "Turnout and last-minute shifts under BW's proportional representation can still alter seat counts though CDU remains the most likely to win the most seats."
  ],
  "confidence": "high",
  "narrative": "Late-February polling places the CDU as the leading party in Baden-Württemberg with a tight margin, and the state's 120-seat MMP system tends to translate vote lead into seat lead but not deterministically. Given Greens’ momentum but continuing CDU lead, the posterior probability that CDU wins the most seats is high but not guaranteed.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Reference class: Baden-Württemberg Landtag elections under mixed-member proportional representation; anchor probability derived from late-February polls showing CDU ahead but with Greens closing gap; base-rate assumed as the starting point before explicit updates."
    },
    "factor_updates": [
      {
        "factor": "Poll lead margin for CDU vs Greens (late Feb 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls show CDU ahead around 28–29% with Greens in the low- to mid-20s, which supports CDU having the most seats under BW's proportional system."
      },
      {
        "factor": "Greens closing gap relative to CDU in some polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens near 22–23% while CDU remains high-20s in some polls, narrowing CDU’s lead and reducing confidence in CDU securing the most seats."
      },
      {
        "factor": "Prediction markets indicate CDU-first scenario (Greens second)",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Polymarket implies CDU would have the most seats; supports CDU-first despite Greens momentum."
      },
      {
        "factor": "Expert polling and media coverage corroborate CDU lead in Feb 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Feb 2026 ZDF Politbarometer Extra and other polls show CDU ahead; corroborates anchor and updates toward CDU-first."
      },
      {
        "factor": "Lead narrows over time in earlier forecasts (Oct 2025–Feb 2026)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Prior forecasts suggested potential Green catch-up; this introduces downside risk to CDU’s seat lead."
      }
    ],
    "synthesis_rationale": "Starting from a mid-range anchor of 0.60 based on pre-election polling, we incorporate updates from five causal factors that push probability up or down. While Greens regain some ground and late headlines show a narrowing lead, the convergence of multiple independent signals toward CDU ahead, and the mechanics of BW's 120-seat MMP system, yield a high posterior probability that CDU wins the most seats. Calibrated to reflect potential correlations among polls and market signals, the final estimate remains high but acknowledges residual uncertainty due to turnout effects and regional variances."
  }
}

